using System.Diagnostics;
using System.IO.MemoryMappedFiles;
using System.Text.Json;
using NAudio.CoreAudioApi;
using NAudio.Wave;
namespace OpenEQ;
internal static class NativeApoRecoveryChecks {
 public static int Owner(string id,string ready){var p=Preset.Flat();p.Output.Protection=false;p.Bands.Clear();p.Bands.Add(new Band{Frequency=1000,Gain=-12.1,Q=2,Channel="left"});using var control=new NativeApo(id,p,false);File.WriteAllText(ready,Environment.ProcessId.ToString());Thread.Sleep(60000);return 0;}
 public static int Run(string path,string name){var report=new Dictionary<string,object>();Process? child=null;string ready=Path.GetFullPath(path+".ready");NativeApo? cleanup=null;
  try{var selected=AudioEngine.Devices().Single(d=>d.Name.Contains(name,StringComparison.OrdinalIgnoreCase));using var en=new MMDeviceEnumerator();using var device=en.GetDevice(selected.Id);var mix=device.AudioClient.MixFormat;var start=new ProcessStartInfo(Environment.ProcessPath!){UseShellExecute=false,CreateNoWindow=true};if(string.Equals(Path.GetFileNameWithoutExtension(Environment.ProcessPath),"dotnet",StringComparison.OrdinalIgnoreCase))start.ArgumentList.Add(Path.Combine(AppContext.BaseDirectory,"OpenDSP.dll"));start.ArgumentList.Add("--apo-crash-owner");start.ArgumentList.Add(selected.Id);start.ArgumentList.Add(ready);if(File.Exists(ready))File.Delete(ready);child=Process.Start(start)??throw new Exception("Could not start owned crash-test controller");for(int n=0;n<50&&!File.Exists(ready)&&!child.HasExited;n++)Thread.Sleep(100);if(!File.Exists(ready))throw new Exception("Crash-test controller did not become ready");using var stream=new FileStream(NativeApo.ConfigPath(selected.Id),FileMode.Open,FileAccess.ReadWrite,FileShare.ReadWrite);using var map=MemoryMappedFile.CreateFromFile(stream,null,4096,MemoryMappedFileAccess.ReadWrite,HandleInheritability.None,true);using var view=map.CreateViewAccessor();using var output=new WasapiOut(device,AudioClientShareMode.Shared,true,60);output.Init(new FloatProvider(new Tone(mix.SampleRate),mix));output.Play();
   double[] Snapshot()=>new[]{view.ReadDouble(1456),view.ReadDouble(1472)};double Measure(){var before=Snapshot();Thread.Sleep(1100);var after=Snapshot();return 10*Math.Log10((after[1]-before[1])/(after[0]-before[0]));}Thread.Sleep(400);double active=Measure();if(Math.Abs(active+12.1)>.05)throw new Exception("Crash-test EQ was not active: "+active);int childId=child.Id;child.Kill();child.WaitForExit();var wait=Stopwatch.StartNew();while(view.ReadUInt32(1532)==0&&wait.ElapsedMilliseconds<11000)Thread.Sleep(100);if(view.ReadUInt32(1532)!=1)throw new Exception("Audio host did not expire the dead controller lease");long recovered=wait.ElapsedMilliseconds;Thread.Sleep(100);double bypass=Measure();if(Math.Abs(bypass)>.0001)throw new Exception("Dead controller did not restore original audio: "+bypass);output.Stop();report["result"]="PASS";report["device"]=selected.Name;report["active_gain_db"]=active;report["after_process_termination_db"]=bypass;report["owned_controller_pid"]=childId;report["recovery_ms"]=recovered;report["audio_process"]=view.ReadUInt32(1500);report["sample_rate"]=view.ReadUInt32(1488);report["scope"]="Only the owned diagnostic controller was terminated; native Windows audio continued and automatically bypassed EQ.";return 0;
  }catch(Exception e){report["result"]="FAIL";report["exception"]=e.ToString();return 1;}finally{if(child!=null&&!child.HasExited){child.Kill();child.WaitForExit();}child?.Dispose();try{var selected=AudioEngine.Devices().Single(d=>d.Name.Contains(name,StringComparison.OrdinalIgnoreCase));cleanup=new NativeApo(selected.Id,Preset.Flat(),false);cleanup.Dispose();}catch(Exception e){report["cleanup_error"]=e.ToString();}if(File.Exists(ready))File.Delete(ready);File.WriteAllText(path,JsonSerializer.Serialize(report,new JsonSerializerOptions{WriteIndented=true}));}}
 sealed class Tone:ISampleProvider {long frame;readonly int rate;public WaveFormat WaveFormat{get;}public Tone(int rate){this.rate=rate;WaveFormat=WaveFormat.CreateIeeeFloatWaveFormat(rate,2);}public int Read(float[] b,int offset,int count){for(int n=offset;n+1<offset+count;n+=2){float x=(float)(.003*Math.Sin(2*Math.PI*1000*frame++/rate));b[n]=b[n+1]=x;}return count;}}
}
